// Extract webhook input
const input = $json.body || $json;
const zipCode = input.zip_code || '63365';
const city = input.city || 'Unknown';
const county = input.county || 'Unknown';
const state = input.state || 'Unknown';
const exitStrategy = input.exit_strategy || 'Fix & Flip';
const buyBox = input.buy_box_criteria || {};

// Store for later nodes
return {
  zip_code: zipCode,
  city: city,
  county: county,
  state: state,
  exit_strategy: exitStrategy,
  buy_box_criteria: buyBox
};

// Collect all 5 agent responses
const input = $('Extract Input').item.json;
const agent1 = $('Agent 1: Property Stock').item.json.choices?.[0]?.message?.content || '{}';
const agent2 = $('Agent 2: Financial & Equity').item.json.choices?.[0]?.message?.content || '{}';
const agent3 = $('Agent 3: Distress & Legal').item.json.choices?.[0]?.message?.content || '{}';
const agent4 = $('Agent 4: Ownership & Occupancy').item.json.choices?.[0]?.message?.content || '{}';
const agent5 = $('Agent 5: Market Dynamics').item.json.choices?.[0]?.message?.content || '{}';

// Build Layer 2 Analyst Prompt
const layer2Prompt = `You are a real estate market analyst synthesizing intelligence for ${input.zip_code} in ${input.city}, ${input.county}, ${input.state} through the lens of a ${input.exit_strategy} investment strategy.

You have received 5 independent research reports from strategy-blind agents. Your job is to apply mosaic theory: connect patterns across these reports that no single agent could have identified alone, then assess whether this zip presents HIGH or LOW signal for the specified exit strategy.

## INPUT DATA

### CLIENT EXIT STRATEGY:
${input.exit_strategy}

### CLIENT BUY BOX CRITERIA:
${JSON.stringify(input.buy_box_criteria, null, 2)}

### RESEARCH REPORT 1: Property Stock Analyst
${agent1}

### RESEARCH REPORT 2: Financial & Equity Analyst
${agent2}

### RESEARCH REPORT 3: Distress & Legal Analyst
${agent3}

### RESEARCH REPORT 4: Ownership & Occupancy Analyst
${agent4}

### RESEARCH REPORT 5: Market Dynamics & Momentum Analyst
${agent5}

## YOUR TASK: MOSAIC SYNTHESIS

Connect patterns ACROSS reports. Look for:
- Death + Absentee + Equity patterns
- Foreclosure + Portfolio + ARM patterns  
- Renovation catalyst patterns
- Teardown opportunity patterns

Apply the ${input.exit_strategy} lens to assess relevance.

Classify as HIGH SIGNAL or LOW SIGNAL with confidence score (0.0-1.0).

## OUTPUT SCHEMA (Return ONLY valid JSON):

{
  "zip_code": "${input.zip_code}",
  "city": "${input.city}",
  "county": "${input.county}",
  "state": "${input.state}",
  "exit_strategy": "${input.exit_strategy}",
  "signal_classification": "HIGH or LOW",
  "confidence": 0.0 to 1.0,
  "dominant_profiles": ["heirs", "absentee_out_of_state", "equity_rich", "aging_owners"],
  "observed_combinations": [
    {
      "name": "Combination name",
      "prevalence": "high/moderate/low",
      "evidence": "Agent X reported Y",
      "signal_strength": "strong/moderate/weak",
      "relevance_to_strategy": "Why this matters for ${input.exit_strategy}"
    }
  ],
  "median_value": 285000,
  "lat": 38.7123,
  "lng": -90.8845,
  "insight": "2-3 sentence client-facing summary",
  "reasoning": "Detailed synthesis showing how you connected patterns across reports"
}

Output ONLY the JSON. No markdown fences, no explanatory text.`;

// Return for Claude call
return {
  model: 'claude-opus-4-5-20251101',
  max_tokens: 8000,
  temperature: 0.1,
  messages: [{ role: 'user', content: layer2Prompt }]
};

// Parse Layer 2 output
const claudeResponse = $json.content?.[0]?.text || '{}';

// Clean JSON if wrapped in markdown
let cleanedResponse = claudeResponse;
if (claudeResponse.includes('```json')) {
  const match = claudeResponse.match(/```json\s*([\s\S]*?)\s*```/);
  if (match) cleanedResponse = match[1];
}

// Parse and return
try {
  const layer2Output = JSON.parse(cleanedResponse);
  return layer2Output;
} catch (e) {
  return {
    error: 'Failed to parse Layer 2 output',
    raw: cleanedResponse.substring(0, 500)
  };
}
